  let a;
  a = pow10(4);
  assertEquals(a, 10000);
  a = pow10(2);
  assertEquals(a, 100);
  a = pow10(0);
  assertEquals(a, 1);
});


Deno.test("log2", () => {
  let a;
  a = log2(64);
  assertEquals(a, 6);
  a = log2(31);
  assertEquals(a, 4);
  a = log2(1);
  assertEquals(a, 0);
});


Deno.test("log10", () => {
